"""Adapt the pinned API bundle to Chrome MV3 without inline script injection."""
from pathlib import Path

folder = Path(__file__).parent
bundle = folder / 'darkreader.js'
source = bundle.read_text()
assert 'Dark Reader v4.9.133' in source
start = source.index('    function injectProxy(')
end = source.index('\n    const definedCustomElements', start)
proxy = source[start:end].strip()
header = '// Dark Reader v4.9.133 proxy (MIT, darkreader.LICENSE). Generated by prepare-darkreader.py.\n'
wrapper = '''
(() => {
    if (globalThis.focusDarkProxyLoaded) return;
    globalThis.focusDarkProxyLoaded = true;
    let active = false;
    document.addEventListener('__darkreader__cleanUp', () => { active = false; });
    document.addEventListener('__focus_darkreader_proxy', (event) => {
        if (active || typeof event.detail !== 'string') return;
        let config;
        try { config = JSON.parse(event.detail); } catch { return; }
        if (typeof config.styleSheets !== 'boolean' || typeof config.customElements !== 'boolean') return;
        active = true;
        injectProxy(config.styleSheets, config.customElements);
    });
PROXY
    document.dispatchEvent(new Event('__focus_darkreader_proxy_ready'));
})();
'''
(folder / 'darkreader-proxy.js').write_text(header + wrapper.replace('PROXY', proxy))
old = '''        {
            const proxyScript = createOrUpdateScript("darkreader--proxy");
            proxyScript.append(
                `(${injectProxy})(${enableStyleSheetsProxy}, ${enableCustomElementRegistryProxy})`
            );
            document.head.insertBefore(proxyScript, rootVarsStyle.nextSibling);
            proxyScript.remove();
        }'''
new = '''        document.dispatchEvent(new CustomEvent("__focus_darkreader_proxy", {
            detail: JSON.stringify({styleSheets: enableStyleSheetsProxy, customElements: enableCustomElementRegistryProxy})
        }));'''
assert source.count(old) == 1
source = source.replace(old, new)
source = source[:start] + source[end:]
old_error = '''            } catch (error) {
                console.error(error);
                messageListeners.forEach((cb) =>'''
new_error = '''            } catch (error) {
                if (args[0].data.responseType !== "data-url") console.error(error);
                messageListeners.forEach((cb) =>'''
assert source.count(old_error) == 1
source = source.replace(old_error, new_error)
bundle.write_bytes(source.replace('\n', '\r\n').encode())
